list_payment_gateways.code:
var response = await client.PaymentGateways.ListPaymentGatewaysAsync(
    new Dictionary<string, object?> { ["limit"] = 20, ["offset"] = 0, ["promotional"] = "false" });
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
foreach (var paymentGateway in ((IReadOnlyList<object?>)body["payment_gateways"]!).Cast<IReadOnlyDictionary<string, object?>>())
    Console.WriteLine($"{paymentGateway["id"]} {paymentGateway["code"]} {paymentGateway["name"]} {paymentGateway["enabled"]} {paymentGateway["default"]}");
var pagination = (IReadOnlyDictionary<string, object?>)body["pagination"]!;
Console.WriteLine($"{pagination["total"]} {pagination["has_next"]}");

