get_payment_gateway.code:
var response = await client.PaymentGateways.GetPaymentGatewayAsync(2);
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
var paymentGateway = (IReadOnlyDictionary<string, object?>)body["payment_gateway"]!;
Console.WriteLine($"{paymentGateway["code"]} {paymentGateway["name"]} {paymentGateway["added"]} {paymentGateway["enabled"]}");
Console.WriteLine(string.Join(", ", ((IReadOnlyDictionary<string, object?>)paymentGateway["settings"]!).Keys));

