var response = await client.PaymentGateways.PatchPaymentGatewayAsync(2, new Dictionary<string, object?>
{
    ["allowed_for"] = new Dictionary<string, object?> { ["store_pickup"] = false },
});
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
var paymentGateway = (IReadOnlyDictionary<string, object?>)body["payment_gateway"]!;
var allowedFor = (IReadOnlyDictionary<string, object?>)paymentGateway["allowed_for"]!;
Console.WriteLine($"{allowedFor["shipping"]} {allowedFor["delivery"]} {allowedFor["store_pickup"]}");
